// Internationalization (i18n) system for FlowPOS Pro
export type Language = 'ar' | 'en' | 'tr' | 'fa' | 'ku';

export interface LanguageInfo {
  code: Language;
  name: string;
  nativeName: string;
  direction: 'ltr' | 'rtl';
}

